// FAN/IP platform page: "Play a member's season".
// One member, one season, four posts. Each world (club, brand, artist) reskins the same season;
// every post adds views and media value on the brand's side. Illustrative figures only.
const FONTS = [["PS Big Shoulders", "800", ""], ["PS Archivo", "400 700", ""], ["PS Fraunces", "400", ""], ["PS Figtree", "400 700", ""], ["PS Syne", "800", ""], ["PS DM Sans", "400 700", ""], ["PS Space Mono", "400", ""]];

const CPM = 2; // € per 1,000 views: FAN/IP's default, which each brand can change.

// The same four moments in every world: what changes is the skin and the words.
const SLOTS = [
  { views: 2400, friends: 0, icon: 'photo' },
  { views: 9800, friends: 0, icon: 'video' },
  { views: 31500, friends: 0, icon: 'video' },
  { views: 4600, friends: 2, icon: 'friends' },
];

const WORLDS = {
  aldermoor: {
    name: 'Aldermoor Athletic',
    brand: 'Aldermoor',
    kind: 'Football club',
    sub: 'Athletic, the Kestrels',
    member: 'Jess Calloway',
    first: 'Jess',
    initials: 'JC',
    since: 'Member 04117, since 2019',
    unit: 'points',
    base: 4120,
    tiers: [['Academy', 0], ['First team', 1000], ['Captain', 5000], ['Club legend', 10000]],
    hello: 'Evening, Jess.',
    movesTitle: 'Your hand this season',
    posts: 'posts',
    friends: 'mates',
    minePosts: 'posts this season',
    mineViews: 'views they earned',
    cta: 'Post it',
    moments: [
      { kind: 'Photo', when: 'Matchday 2', title: 'Scarves up: show us yours', pts: 80 },
      { kind: 'Video', when: 'Matchday 6', title: 'Matchday at The Weir, 20 seconds on camera', pts: 150 },
      { kind: 'Video', when: 'Derby day', title: 'The winner against Granby Rovers, from where you stood', pts: 400 },
      { kind: 'Friends', when: 'Matchday 9', title: 'Bring two mates to The Weir', pts: 300 },
    ],
    wrapKicker: 'Season 2026/27',
    wrapTitle: 'Jess’s season at The Weir',
    demo: 'demo/aldermoor/',
  },
  aube: {
    name: 'Maison Aube',
    brand: 'Maison Aube',
    kind: 'Beauty brand',
    sub: 'Le Jardin',
    member: 'Inès Ferrand',
    first: 'Inès',
    initials: 'IF',
    since: 'Member since March 2024',
    unit: 'petals',
    base: 1840,
    tiers: [['Graine', 0], ['Bouton', 1000], ['Fleur', 2480], ['Jardin secret', 6000]],
    hello: 'Bonsoir, Inès.',
    movesTitle: 'Rituels for you',
    posts: 'rituels',
    friends: 'friends',
    minePosts: 'posts with your tag',
    mineViews: 'views they earned',
    cta: 'Post the ritual',
    moments: [
      { kind: 'Photo', when: 'September', title: 'Your shelf, with one Aube favourite on it', pts: 100 },
      { kind: 'Review', when: 'October', title: 'A review in 15 seconds', pts: 150 },
      { kind: 'Unboxing', when: 'Givre launch', title: 'Unbox your Givre coffret on camera', pts: 250 },
      { kind: 'Friends', when: 'November', title: 'Tag two friends who need this', pts: 200 },
    ],
    wrapKicker: 'Le Jardin, autumn',
    wrapTitle: 'Inès’s season in le Jardin',
    demo: 'demo/maison-aube/',
  },
  ilsa: {
    name: 'Ilsa Morrow',
    brand: 'Ilsa Morrow',
    kind: 'Artist on tour',
    sub: 'The Band, Marée haute tour',
    member: 'Maëlle Kerbrat',
    first: 'Maëlle',
    initials: 'MK',
    since: 'since 2023, Nantes',
    unit: 'notes',
    base: 2140,
    tiers: [['Listener', 0], ['Singalong', 1000], ['Encore', 2520], ['Soundcheck', 6000]],
    hello: 'Next stop, <em>Lyon.</em>',
    movesTitle: 'Your setlist this tour',
    posts: 'posts',
    friends: 'friends',
    minePosts: 'posts on tour',
    mineViews: 'views on your posts',
    cta: 'Post it',
    moments: [
      { kind: 'Photo', when: 'Nantes', title: 'Setlist photo from the Nantes show', pts: 120 },
      { kind: 'Video', when: 'Bordeaux', title: 'Sing the chorus of ‘Marée haute’', pts: 200 },
      { kind: 'Video', when: 'Lyon', title: 'The encore in Lyon, from the front row', pts: 250 },
      { kind: 'Friends', when: 'Geneva', title: 'Bring two friends to the Geneva show', pts: 200 },
    ],
    wrapKicker: 'Marée haute tour',
    wrapTitle: 'Maëlle’s tour',
    demo: 'demo/ilsa-morrow/',
  },
};

const ICONS = {
  photo: '<rect x="3.5" y="7" width="17" height="12" rx="1.5"/><circle cx="12" cy="13" r="3.5"/><path d="M9 7l1.5-2.5h3L15 7"/>',
  video: '<rect x="3.5" y="6" width="12" height="12" rx="1.5"/><path d="M15.5 10.5 20.5 7.5v9l-5-3"/>',
  friends: '<circle cx="9" cy="9" r="3.2"/><path d="M3.5 19c.6-3 2.8-4.6 5.5-4.6s4.9 1.6 5.5 4.6M17 8v6M14 11h6"/>',
  check: '<path d="M5 12.5l4.5 4.5L19 7.5"/>',
};
const icon = (k) => `<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">${ICONS[k]}</svg>`;

// World marks, drawn for this page (fictional).
const CREST = '<svg viewBox="0 0 40 46" aria-hidden="true" focusable="false"><path d="M20 1.5 37.5 6v15.5C37.5 33 29.6 41 20 44.5 10.4 41 2.5 33 2.5 21.5V6z" fill="#fff" stroke="#17263a" stroke-width="2.5"/><path d="M20 5.5 33.5 9v12.5C33.5 31 27.4 37.6 20 40.5 12.6 37.6 6.5 31 6.5 21.5V9z" fill="#17263a"/><path d="M8.5 15.5c4 .4 8 2.6 11.5 6.6 3.5-4 7.5-6.2 11.5-6.6-2.2 3.6-5.6 6.6-9.6 8.2l-1.9 6.3-1.9-6.3c-4-1.6-7.4-4.6-9.6-8.2z" fill="#c9421b"/><circle cx="20" cy="17.5" r="2.3" fill="#f0e2c4"/><path d="M13 34.5h14" stroke="#f0e2c4" stroke-width="1.6"/></svg>';
const ARCH = '<svg viewBox="0 0 30 36" aria-hidden="true" focusable="false"><path d="M3 35V15a12 12 0 0 1 24 0v20" fill="none" stroke="currentColor" stroke-width="2"/><path d="M8 35v-6a7 7 0 0 1 14 0v6z" fill="#c26f63"/><path d="M1 35h28" stroke="currentColor" stroke-width="2"/></svg>';
const ROSE = '<svg viewBox="0 0 80 120" aria-hidden="true" focusable="false"><path d="M40 118V52" stroke="#4a5b50" stroke-width="2.5" fill="none"/><path d="M40 88c-10-2-17-9-19-17 9 0 16 5 19 13M40 76c9-3 15-10 16-18-8 1-14 7-16 14" fill="#8b9b83"/><path d="M40 20c-9 6-13 16-11 25 2 7 7 10 11 10s9-3 11-10c2-9-2-19-11-25z" fill="#c26f63"/><path d="M40 28c-4 5-5 12-3 18M40 28c4 5 5 12 3 18" stroke="#9e4f45" stroke-width="1.6" fill="none"/></svg>';
const WAVES = '<svg viewBox="0 0 300 90" preserveAspectRatio="none" aria-hidden="true" focusable="false"><path d="M0 22c25-14 50-14 75 0s50 14 75 0 50-14 75 0 50 14 75 0" /><path d="M0 44c25-14 50-14 75 0s50 14 75 0 50-14 75 0 50 14 75 0" /><path d="M0 66c25-14 50-14 75 0s50 14 75 0 50-14 75 0 50 14 75 0" /><path d="M0 88c25-14 50-14 75 0s50 14 75 0 50-14 75 0 50 14 75 0" /></svg>';

const fmt = (n) => Math.round(n).toLocaleString('en-GB');
const euro = (n) => '€' + n.toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const short = (n) => (n >= 1000 ? (n / 1000).toFixed(n >= 10000 ? 1 : 1).replace(/\.0$/, '') + 'k' : String(n));
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);

function loadFonts() {
  if (!('FontFace' in window) || !document.fonts) return;
  for (const [family, weight, b64] of FONTS) {
    try {
      const bin = atob(b64);
      const buf = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) buf[i] = bin.charCodeAt(i);
      const face = new FontFace(family, buf.buffer, { weight, display: 'swap' });
      document.fonts.add(face);
      face.load().catch(() => {});
    } catch (e) { /* fallback fonts stay */ }
  }
}

function init() {
  const root = document.querySelector('[data-play]');
  if (!root) return;
  loadFonts();
  const $ = (s) => root.querySelector(s);
  const $$ = (s) => [...root.querySelectorAll(s)];
  const motion = matchMedia('(prefers-reduced-motion: no-preference)');

  const stage = $('.ps-stage');
  const end = $('.ps-end');
  const live = $('[data-live]');
  const moves = $('.ps-moves');
  const feed = $('.ps-feed');
  const playAll = $('[data-play-all]');
  const demoLink = $('[data-demo-link]');

  let world = (root.querySelector('input[name="play-world"]:checked') || {}).value || 'aldermoor';
  let done = [false, false, false, false];
  let shown = { views: 0, value: 0 }; // what the counters display, for count-ups
  let busy = false;

  const W = () => WORLDS[world];
  const totals = () => {
    let views = 0, friends = 0, posts = 0, pts = 0;
    done.forEach((d, i) => {
      if (!d) return;
      posts++;
      views += SLOTS[i].views;
      friends += SLOTS[i].friends;
      pts += W().moments[i].pts;
    });
    return { views, friends, posts, pts, value: (views / 1000) * CPM };
  };
  const tierOf = (bal) => W().tiers.reduce((acc, t, i) => (bal >= t[1] ? i : acc), 0);

  function countTo(el, from, to, format, ms = 900) {
    if (!el) return;
    if (!motion.matches || from === to) { el.textContent = format(to); return; }
    const t0 = performance.now();
    const step = (t) => {
      const k = Math.min((t - t0) / ms, 1);
      const e = 1 - Math.pow(1 - k, 3);
      el.textContent = format(from + (to - from) * e);
      if (k < 1) requestAnimationFrame(step);
    };
    requestAnimationFrame(step);
  }

  function cardHTML(w, bal, tier) {
    const t = w.tiers[tier][0];
    if (world === 'aldermoor') {
      return `<div class="ps-card__face"><span class="ps-card__crest">${CREST}</span><span class="ps-card__tier" data-tier>${esc(t)}</span>
        <p class="ps-card__name">${esc(w.member)}</p><p class="ps-card__since">${esc(w.since)}</p>
        <p class="ps-card__bal"><b data-bal>${fmt(bal)}</b> ${w.unit}</p></div>
        <span class="ps-card__strip" aria-hidden="true">17</span>`;
    }
    if (world === 'aube') {
      return `<div class="ps-card__frame"><span class="ps-card__arch">${ROSE}</span>
        <div class="ps-card__main"><p class="ps-card__top"><span>Le Jardin</span><span>N° 02417</span></p>
        <p class="ps-card__name">${esc(w.member)}</p><p class="ps-card__since">${esc(w.since)}</p>
        <p class="ps-card__bal"><b data-bal>${fmt(bal)}</b> <span>${w.unit}</span><span class="ps-card__tier" data-tier>${esc(t)}</span></p></div></div>`;
    }
    return `<span class="ps-card__band" aria-hidden="true">The Band</span><div class="ps-card__main">
      <p class="ps-card__top"><span>Marée haute tour</span><span>N° 0731</span></p>
      <p class="ps-card__name">${esc(w.member)}</p><p class="ps-card__since"><span class="ps-card__tier" data-tier>${esc(t)}</span> ${esc(w.since)}</p>
      <span class="ps-card__waves">${WAVES}</span>
      <p class="ps-card__bal"><b data-bal>${fmt(bal)}</b> ${w.unit}</p></div>`;
  }

  function shareHTML(w, tot, tier) {
    const stats = [
      [fmt(tot.posts), w.posts],
      [short(tot.views), 'views'],
      [w.tiers[tier][0], 'reached'],
      [fmt(tot.friends), w.friends + ' brought in'],
    ];
    const mark = world === 'aldermoor' ? `<span class="ps-share__mark">${CREST}</span>` : world === 'aube' ? `<span class="ps-share__mark">${ARCH}</span>` : '<span class="ps-share__mark ps-share__mark--type">Ilsa<br>Morrow</span>';
    return `${mark}<p class="ps-share__kicker">${esc(w.wrapKicker)}</p><p class="ps-share__title">${esc(w.wrapTitle)}</p>
      <dl class="ps-share__stats">${stats.map(([v, l]) => `<div><dd>${esc(v)}</dd><dt>${esc(l)}</dt></div>`).join('')}</dl>
      <p class="ps-share__foot">${esc(w.name)}</p>`;
  }

  function renderWorld() {
    const w = W();
    stage.dataset.psWorld = world;
    end.dataset.psWorld = world;
    $$('[data-w]').forEach((el) => {
      const key = el.dataset.w;
      if (key === 'hello') el.innerHTML = w.hello;
      else el.textContent = w[key];
    });
    $('.ps-app__logo').innerHTML = world === 'aldermoor' ? CREST : world === 'aube' ? ARCH : '';
    if (demoLink) { demoLink.href = w.demo; demoLink.textContent = `Open the full ${w.brand} demo`; }
    moves.innerHTML = w.moments.map((m, i) => `<li class="ps-move${done[i] ? ' is-done' : ''}" data-slot="${i}">
        <button type="button" class="ps-move__btn" data-slot="${i}"${done[i] ? ' aria-disabled="true"' : ''}>
          <span class="ps-move__pts">+${fmt(m.pts)} <small>${w.unit}</small></span>
          <span class="ps-move__kind"><span class="ps-move__k">${esc(m.kind)}</span><span class="ps-move__when">${esc(m.when)}</span></span>
          <span class="ps-move__title">${esc(m.title)}</span>
          <span class="ps-move__cta"><span class="ps-move__go">${esc(w.cta)}</span><span class="ps-move__out">${icon('check')}<span>Posted · <b data-views>${done[i] ? fmt(SLOTS[i].views) : '0'}</b> views</span></span></span>
        </button></li>`).join('');
    renderState(false);
  }

  function renderState(animate, lastSlot) {
    const w = W();
    const tot = totals();
    const bal = w.base + tot.pts;
    const tier = tierOf(bal);
    const next = w.tiers[tier + 1];
    const prevTier = Number(stage.dataset.tier || tier);

    // Member side: card, level, moves.
    const card = $('.ps-card');
    if (!animate || !card.querySelector('[data-bal]')) card.innerHTML = cardHTML(w, bal, tier);
    else {
      const b = card.querySelector('[data-bal]');
      countTo(b, w.base + tot.pts - w.moments[lastSlot].pts, bal, fmt, 700);
      const tEl = card.querySelector('[data-tier]');
      tEl.textContent = w.tiers[tier][0];
      if (tier > prevTier) { card.classList.remove('is-up'); void card.offsetWidth; card.classList.add('is-up'); }
    }
    stage.dataset.tier = tier;
    const lo = w.tiers[tier][1];
    const hi = next ? next[1] : lo + 1;
    $('[data-level-line]').textContent = next
      ? `${fmt(next[1] - bal)} ${w.unit} to ${next[0]}`
      : `${w.tiers[tier][0]}, the top level`;
    if (tier > 1 && done.every(Boolean)) $('[data-level-line]').textContent = `${w.tiers[tier][0]} reached this season`;
    $('[data-level-fill]').style.setProperty('--fill', ((tier + Math.min((bal - lo) / (hi - lo), 1)) / (w.tiers.length - 1) * 100).toFixed(1) + '%');
    $('.ps-level__steps').innerHTML = w.tiers.map((t, i) => `<li class="${i < tier ? 'is-past' : i === tier ? 'is-now' : ''}">${esc(t[0])}</li>`).join('');

    // Brand side: the result.
    const from = shown;
    $$('[data-r="views"]').forEach((el) => (animate ? countTo(el, from.views, tot.views, fmt) : (el.textContent = fmt(tot.views))));
    $$('[data-r="value"]').forEach((el) => (animate ? countTo(el, from.value, tot.value, euro) : (el.textContent = euro(tot.value))));
    shown = { views: tot.views, value: tot.value };
    $$('[data-r="posts"]').forEach((el) => (el.textContent = `${tot.posts}/4`));
    $$('[data-r="friends"]').forEach((el) => (el.textContent = fmt(tot.friends)));
    $$('[data-m="posts"]').forEach((el) => (el.textContent = fmt(tot.posts)));
    $$('[data-m="views"]').forEach((el) => (el.textContent = short(tot.views)));
    $$('[data-r="first"]').forEach((el) => (el.textContent = w.first));
    $$('[data-r="brand"]').forEach((el) => (el.textContent = w.brand));

    const order = stage._order || [];
    feed.innerHTML = order.length
      ? order.map((i) => {
          const s = SLOTS[i], m = w.moments[i];
          return `<li class="ps-feed__item${animate && i === lastSlot ? ' is-new' : ''}"><span class="ps-feed__ico">${icon(s.icon)}</span>
            <span class="ps-feed__t">${esc(m.title)}<small>${esc(m.kind)} · ${esc(m.when)}${s.friends ? ` · ${s.friends} new members` : ''}</small></span>
            <span class="ps-feed__v"><b>+${fmt(s.views)}</b> views<small>+${euro((s.views / 1000) * CPM)}</small></span></li>`;
        }).join('')
      : '<li class="ps-feed__empty">Nothing posted yet. Tap a moment in the app.</li>';

    const all = done.every(Boolean);
    playAll.hidden = all;
    renderEnd(all, tot, tier);
  }

  function renderEnd(show, tot, tier) {
    const w = W();
    if (!show) { end.hidden = true; return; }
    end.querySelector('.ps-share').innerHTML = shareHTML(w, tot, tier);
    end.querySelector('[data-e="title"]').innerHTML = `${esc(w.first)} brought ${esc(w.brand)} <em>${fmt(tot.views)} views.</em>`;
    end.querySelector('[data-e="posts"]').textContent = fmt(tot.posts);
    end.querySelector('[data-e="views"]').textContent = fmt(tot.views);
    end.querySelector('[data-e="value"]').textContent = euro(tot.value);
    end.querySelector('[data-e="friends"]').textContent = fmt(tot.friends);
    const wasHidden = end.hidden;
    end.hidden = false;
    if (wasHidden && motion.matches) { end.classList.remove('is-in'); void end.offsetWidth; end.classList.add('is-in'); }
  }

  function post(i, quiet) {
    if (done[i]) return;
    const w = W();
    done[i] = true;
    stage._order = [...(stage._order || []), i];
    const before = tierOf(w.base + totals().pts - w.moments[i].pts);
    const li = moves.querySelector(`li[data-slot="${i}"]`);
    li.classList.add('is-done');
    li.querySelector('button').setAttribute('aria-disabled', 'true');
    countTo(li.querySelector('[data-views]'), 0, SLOTS[i].views, fmt, 900);
    renderState(true, i);
    const tot = totals();
    const tier = tierOf(w.base + tot.pts);
    let msg = `Posted: ${w.moments[i].title}. Plus ${fmt(w.moments[i].pts)} ${w.unit}. ${fmt(SLOTS[i].views)} views, worth ${euro((SLOTS[i].views / 1000) * CPM)} in media.`;
    if (SLOTS[i].friends) msg += ` ${SLOTS[i].friends} friends joined.`;
    if (tier > before) msg += ` New level: ${w.tiers[tier][0]}.`;
    if (done.every(Boolean)) msg += ` Season over: ${w.first} brought ${w.brand} ${fmt(tot.views)} views, worth ${euro(tot.value)}.`;
    if (!quiet) live.textContent = msg;
  }

  moves.addEventListener('click', (e) => {
    const b = e.target.closest('.ps-move__btn');
    if (!b || busy) return;
    post(Number(b.dataset.slot));
  });

  playAll.addEventListener('click', () => {
    if (busy) return;
    const left = done.map((d, i) => (d ? -1 : i)).filter((i) => i >= 0);
    if (!motion.matches) { left.forEach((i) => post(i, true)); live.textContent = `Season over: ${W().first} brought ${W().brand} ${fmt(totals().views)} views, worth ${euro(totals().value)}.`; return; }
    busy = true;
    left.forEach((i, k) => setTimeout(() => {
      post(i, k < left.length - 1);
      if (k === left.length - 1) busy = false;
    }, k * 650));
  });

  $('[data-reset]').addEventListener('click', () => {
    done = [false, false, false, false];
    stage._order = [];
    shown = { views: 0, value: 0 };
    busy = false;
    renderWorld();
    live.textContent = 'Season restarted.';
  });

  $$('input[name="play-world"]').forEach((r) => r.addEventListener('change', () => {
    if (!r.checked) return;
    world = r.value;
    renderWorld();
    live.textContent = `Now in ${W().name}’s colours and words. Same season, same results.`;
  }));

  renderWorld();
}

init();
